function art(p){return `<svg viewBox="0 0 180 150" aria-label="${esc(p.name)}のイメージ" role="img"><path fill="${p.fill}" stroke="#8c9c90" stroke-width="1.5" d="${p.pants?'M48 15H132L140 138H104L90 62L77 138H40Z':p.apron?'M64 28L72 10H108L116 28L132 136H48Z':'M60 17L78 12L90 25L102 12L120 17L156 55L133 75L122 61V138H58V61L47 75L24 55Z'}"/>${!p.pants?'<path d="M90 30V130M66 66H80V83H66" fill="none" stroke="#ffffff80"/>':''}</svg>`}
